pm.test("Response has post object", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property('post');
    pm.expect(jsonData.post).to.be.an('object');
});

// Test 4: Post has all required fields
pm.test("Post has all required fields", function () {
    const jsonData = pm.response.json();
    const post = jsonData.post;
    pm.expect(post).to.have.all.keys(
        'id', 'title', 'content', 'author', 'created_at', 'updated_at'
    );
    pm.expect(post.id).to.be.a('number');
    pm.expect(post.title).to.be.a('string');
    pm.expect(post.content).to.be.a('string');
    pm.expect(post.author).to.be.a('string');
});

// Test 5: Post ID matches the requested ID
pm.test("Post ID matches requested ID", function () {
    const jsonData = pm.response.json();
    const url = pm.request.url.toString();
    const requestedId = parseInt(url.split('/').pop());
    pm.expect(jsonData.post.id).to.equal(requestedId);
});
